import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.CWdVbaJB.js";const u=JSON.parse('{"title":"Traces","description":"","frontmatter":{"title":"Traces"},"headers":[],"relativePath":"tracing/overview.md","filePath":"tracing/overview.md"}'),i={name:"tracing/overview.md"};function d(n,e,c,s,l,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="traces" tabindex="-1">Traces <a class="header-anchor" href="#traces" aria-label="Permalink to &quot;Traces&quot;">​</a></h1><p>Traces are the core data unit in SHAVIRA. Every LLM call, tool invocation, and agent step is captured as a structured trace with metadata, cost, and timing information.</p><h2 id="trace-structure" tabindex="-1">Trace Structure <a class="header-anchor" href="#trace-structure" aria-label="Permalink to &quot;Trace Structure&quot;">​</a></h2><p>Each trace contains:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>traceId</code></td><td>Unique identifier for the trace</td></tr><tr><td><code>name</code></td><td>Descriptive name (e.g., <code>main-chat-flow</code>, <code>incident-summary</code>)</td></tr><tr><td><code>eventType</code></td><td>Type of event (<code>trace.start</code>, <code>span.end</code>, <code>cost.record</code>, etc.)</td></tr><tr><td><code>status</code></td><td>Current status of the trace</td></tr><tr><td><code>provider</code></td><td>LLM provider (OpenAI, Anthropic, Google, etc.)</td></tr><tr><td><code>model</code></td><td>Model used (gpt-4o, claude-3.5-sonnet, etc.)</td></tr><tr><td><code>environment</code></td><td>Deployment environment (local, staging, prod)</td></tr><tr><td><code>serviceName</code></td><td>Logical service name</td></tr><tr><td><code>userId</code></td><td>End user identifier</td></tr><tr><td><code>sessionId</code></td><td>Session grouping identifier</td></tr><tr><td><code>projectId</code></td><td>Project assignment</td></tr><tr><td><code>costUsd</code></td><td>Computed cost in USD</td></tr></tbody></table><h2 id="viewing-traces" tabindex="-1">Viewing Traces <a class="header-anchor" href="#viewing-traces" aria-label="Permalink to &quot;Viewing Traces&quot;">​</a></h2><p>The Traces view displays a searchable, filterable table of all traces in your workspace.</p><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>Use the search bar to find traces by name. The search is fuzzy — partial matches work.</p><h3 id="facet-sidebar" tabindex="-1">Facet Sidebar <a class="header-anchor" href="#facet-sidebar" aria-label="Permalink to &quot;Facet Sidebar&quot;">​</a></h3><p>The left sidebar provides six filter groups:</p><ol><li><strong>Project</strong> — filter by project assignment</li><li><strong>App</strong> — filter by application/service name</li><li><strong>Environment</strong> — filter by deployment environment</li><li><strong>Service</strong> — filter by service name</li><li><strong>Trace name</strong> — filter by trace name pattern</li><li><strong>User</strong> — text input for fuzzy matching on user ID</li></ol><p>Each group with more than 3 options includes a search box for quick filtering. Use the &quot;Clear all&quot; button to reset filters.</p><h3 id="trace-detail" tabindex="-1">Trace Detail <a class="header-anchor" href="#trace-detail" aria-label="Permalink to &quot;Trace Detail&quot;">​</a></h3><p>Click any trace row to open the detail drawer showing:</p><ul><li><strong>Overview</strong> — trace metadata, timing, status</li><li><strong>Payload</strong> — full request/response data</li><li><strong>Spans</strong> — nested span tree with timing</li><li><strong>Cost</strong> — cost breakdown by tier (verified, estimated, reported)</li><li><strong>Raw</strong> — raw JSON event data</li></ul><h2 id="exporting-traces" tabindex="-1">Exporting Traces <a class="header-anchor" href="#exporting-traces" aria-label="Permalink to &quot;Exporting Traces&quot;">​</a></h2><p>Select traces and use the export button to download as:</p><ul><li><strong>CSV</strong> — tabular format for spreadsheets</li><li><strong>NDJSON</strong> — newline-delimited JSON for programmatic processing</li></ul><p>See <a href="/shavira-docs/platform/export.html">Export</a> for details.</p>',20)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
